bool UGomokuItemLibrary::ExecuteItem(UGomokuRuleEngine* Engine, int32 ItemId, int32 PlayerId, const FIntPoint& TargetCell, int32 TargetPlayerIndex)
{
	if (!Engine || !Engine->IsMatchInitialized())
		return false;
	if (ItemId <= 0 || PlayerId <= 0)
		return false;

	const auto* Def = GetItemData(ItemId);
	if (!Def)
		return false;

	// Must be usable now (inventory + not locked + one-per-turn).
	if (!Engine->IsItemUsableNow(PlayerId, ItemId))
		return false;

	// Validate target.
	if (!ValidateTarget(Engine, ItemId, TargetCell, TargetPlayerIndex))
		return false;

	// Consume energy cost.
	if (!Engine->ConsumePlayerEnergy(PlayerId, Def->EnergyCost))
		return false;

	switch (Def->Type)
	{
	case EGomokuItemType::SealStone:
	{
		const auto C = Engine->GetBoardCell(TargetCell.X, TargetCell.Y);
		if (C.State != ECellState::Empty) return false;
		if (!Engine->SetCellBlocked(TargetCell.X, TargetCell.Y, true))
			return false;
		break;
	}
	case EGomokuItemType::SkipTurn:
	{
		const int32 TgtId = (TargetPlayerIndex + 1);
		if (!Engine->SetPlayerSkipNextTurn(TgtId, true))
			return false;
		break;
	}
	case EGomokuItemType::Steal:
	{
		if (Engine->IsCellGuardianProtected(TargetCell.X, TargetCell.Y))
			return false;
		const auto C = Engine->GetBoardCell(TargetCell.X, TargetCell.Y);
		if (C.State == ECellState::Empty) return false;
		if (!Engine->ChangeCellOwnership(TargetCell.X, TargetCell.Y, PlayerId))
			return false;
		break;
	}
	case EGomokuItemType::GuardianBarrier:
	{
		const auto C = Engine->GetBoardCell(TargetCell.X, TargetCell.Y);
		if (C.State == ECellState::Empty) return false;
		if (!Engine->SetCellGuardianProtected(TargetCell.X, TargetCell.Y, true))
			return false;
		break;
	}
	case EGomokuItemType::Pull:
	default:
	{
		// Pull is stubbed for now; return false until implemented.
		return false;
	}
	}

	if (!Engine->RemoveItemFromInventory(PlayerId, ItemId))
		return false;

	Engine->SetUsedItemThisTurn(PlayerId);
	return true;
}

