static UGomokuRuleEngine* MakeStage7Engine(int32 MaxPlayers, int32 BoardSize = 15)
{
	UObject* Outer = GetTransientPackage();
	UGomokuRuleEngine* Engine = NewObject<UGomokuRuleEngine>(Outer);

	FGomokuMatchConfig Config;
	Config.BoardSizeX = BoardSize;
	Config.BoardSizeY = BoardSize;
	Config.WinLength = 5;
	Config.MaxPlayers = MaxPlayers;
	Config.TurnTimeLimit = 30.f;
	Config.InitialEnergyPerPlayer = 10;

	Engine->InitializeMatch(Config);
	return Engine;
}

// Test: Gomoku.Stage7.SealStoneBlocksCell
IMPLEMENT_SIMPLE_AUTOMATION_TEST(
	FGomokuStage7_SealStoneBlocksCell,
	TEXT("Gomoku.Stage7.SealStoneBlocksCell"),
	EAutomationTestFlags::EditorContext | EAutomationTestFlags::EngineFilter)

bool FGomokuStage7_SealStoneBlocksCell::RunTest(const FString& Parameters)
{
	auto* Engine = MakeStage7Engine(2, 15);
	const int32 PlayerId = 1;
	const int32 SealItemId = static_cast<int32>(EGomokuItemType::SealStone);

	// Add item without marking as gained this turn so it is usable immediately.
	bool Added = Engine->AddItemToInventory(PlayerId, SealItemId);
	if (!TestTrue(TEXT("AddItemToInventory succeeds"), Added)) return false;

	// Ensure player has enough energy (SealStone cost 1).
	int32 BeforeEnergy = Engine->GetPlayerStateData(PlayerId).CurrentEnergy;
	if (BeforeEnergy < 1)
	{
		Engine->AddPlayerEnergy(PlayerId, 5, UGomokuItemLibrary::MaxEnergy);
	}

	const FIntPoint Target(5, 5);

	bool Executed = UGomokuItemLibrary::ExecuteItem(Engine, SealItemId, PlayerId, Target, -1);
	if (!TestTrue(TEXT("ExecuteItem succeeds for SealStone"), Executed)) return false;

	auto CellState = Engine->GetBoardCell(Target.X, Target.Y).State;
	if (!TestEqual<ECellState>(TEXT("Cell becomes Blocked after SealStone"), CellState, ECellState::Blocked))
		return false;

	bool IsValidEmpty = UGomokuItemLibrary::IsValidEmpty(Engine, Target);
	if (!TestFalse(TEXT("Sealed cell is not valid empty"), IsValidEmpty)) return false;

	return true;
}

// Test: Gomoku.Stage7.SkipTurnFlagsPlayer
IMPLEMENT_SIMPLE_AUTOMATION_TEST(
	FGomokuStage7_SkipTurnFlagsPlayer,
	TEXT("Gomoku.Stage7.SkipTurnFlagsPlayer"),
	EAutomationTestFlags::EditorContext | EAutomationTestFlags::EngineFilter)

bool FGomokuStage7_SkipTurnFlagsPlayer::RunTest(const FString& Parameters)
{
	auto* Engine = MakeStage7Engine(2, 15);
	const int32 PlayerId = 1;
	const int32 SkipItemId = static_cast<int32>(EGomokuItemType::SkipTurn);

	bool Added = Engine->AddItemToInventory(PlayerId, SkipItemId);
	if (!TestTrue(TEXT("AddItemToInventory succeeds"), Added)) return false;

	// Ensure energy.
	int32 BeforeEnergy = Engine->GetPlayerStateData(PlayerId).CurrentEnergy;
	if (BeforeEnergy < 1)
	{
		Engine->AddPlayerEnergy(PlayerId, 5, UGomokuItemLibrary::MaxEnergy);
	}

	// Use SkipTurn targeting player index 1 => PlayerId 2.
	const FIntPoint DummyTarget(0, 0);
	int32 TargetPlayerIndex = 1; // index of victim (player 2)

	bool Executed = UGomokuItemLibrary::ExecuteItem(Engine, SkipItemId, PlayerId, DummyTarget, TargetPlayerIndex);
	if (!TestTrue(TEXT("ExecuteItem succeeds for SkipTurn"), Executed)) return false;

	const auto& PState = Engine->GetPlayerStateData(2);
	if (!TestTrue(TEXT("Target player bSkipNextTurn is set"), PState.bSkipNextTurn))
		return false;

	return true;
}

// Test: Gomoku.Stage7.NewItemNotUsableSameTurn
IMPLEMENT_SIMPLE_AUTOMATION_TEST(
	FGomokuStage7_NewItemNotUsableSameTurn,
	TEXT("Gomoku.Stage7.NewItemNotUsableSameTurn"),
	EAutomationTestFlags::EditorContext | EAutomationTestFlags::EngineFilter)

bool FGomokuStage7_NewItemNotUsableSameTurn::RunTest(const FString& Parameters)
{
	auto* Engine = MakeStage7Engine(2, 15);
	const int32 PlayerId = 1;
	const int32 ItemId = static_cast<int32>(EGomokuItemType::SealStone);

	bool Added = Engine->AddItemToInventory(PlayerId, ItemId);
	if (!TestTrue(TEXT("AddItemToInventory succeeds"), Added)) return false;

	// Mark as gained this turn => not usable yet.
	Engine->MarkItemGainedThisTurn(PlayerId, ItemId);

	bool CanUseBefore = UGomokuItemLibrary::CanUseItem(Engine, PlayerId, ItemId);
	if (!TestFalse(TEXT("New item not usable same turn"), CanUseBefore)) return false;

	// Clear locks => now usable.
	Engine->ClearTurnItemLocksForPlayer(PlayerId);

	bool CanUseAfter = UGomokuItemLibrary::CanUseItem(Engine, PlayerId, ItemId);
	if (!TestTrue(TEXT("Item usable after lock cleared"), CanUseAfter)) return false;

	return true;
}

// Test: Gomoku.Stage7.EnergyCostConsumed
IMPLEMENT_SIMPLE_AUTOMATION_TEST(
	FGomokuStage7_EnergyCostConsumed,
	TEXT("Gomoku.Stage7.EnergyCostConsumed"),
	EAutomationTestFlags::EditorContext | EAutomationTestFlags::EngineFilter)

bool FGomokuStage7_EnergyCostConsumed::RunTest(const FString& Parameters)
{
	auto* Engine = MakeStage7Engine(2, 15);
	const int32 PlayerId = 1;
	const int32 SealItemId = static_cast<int32>(EGomokuItemType::SealStone);

	bool Added = Engine->AddItemToInventory(PlayerId, SealItemId);
	if (!TestTrue(TEXT("AddItemToInventory succeeds"), Added)) return false;

	// Ensure known energy.
	int32 InitialEnergy = 10;
	Engine->SetPlayerEnergyDirect(PlayerId, InitialEnergy);

	const FIntPoint Target(5, 5);

	bool Executed = UGomokuItemLibrary::ExecuteItem(Engine, SealItemId, PlayerId, Target, -1);
	if (!TestTrue(TEXT("ExecuteItem succeeds for energy test"), Executed)) return false;

	int32 AfterEnergy = Engine->GetPlayerStateData(PlayerId).CurrentEnergy;
	// SealStone cost is 1.
	if (!TestEqual<int32>(TEXT("Energy decreased by item cost"), AfterEnergy, InitialEnergy - 1))
		return false;

	return true;
}

#endif // WITH_DEV_AUTOMATION_TESTS
